const query = $input.first().json.query || {};
const rawRef = String(query.ref || '').trim().toUpperCase();

if (!/^MIS-\d{4}-\d{3,6}$/.test(rawRef)) {
  return [
    {
      json: {
        valid: false,
        httpStatus: 400,
        error: 'Format de référence mission invalide.'
      }
    }
  ];
}

return [
  {
    json: {
      valid: true,
      mission_ref: rawRef
    }
  }
];

const ref = String($('Valider Paramètre Ref').first().json.mission_ref || '').trim().toUpperCase();
const inputData = $input.first().json || {};
const records = Array.isArray(inputData.records)
  ? inputData.records
  : (Array.isArray(inputData.list) ? inputData.list : []);

if (records.length === 0) {
  return [
    {
      json: {
        found: false,
        ok: false,
        statusCode: 404,
        payload: {
          found: false,
          reference: ref,
          error: 'Dossier introuvable'
        }
      }
    }
  ];
}

const record = records[0];
const f = record.fields && typeof record.fields === 'object' ? record.fields : record;

const normalizeKey = (val) =>
  String(val || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();

const statutBrut = String(f.Statut_Mandat || f.Statut || f.Statut_Mission || 'Saisine_Recue').trim();
const sNorm = normalizeKey(statutBrut);

const palierBrut = String(f.Palier_Mandat || f.Palier || f.Option_Audit || '').trim();
const palierKey = normalizeKey(palierBrut);
const isDecouverte = /decouver|palier_1|option a|p1/.test(palierKey);

const rawExpert = f.Expert_Assigne ?? f.Expert_ID ?? f.Expert_Nom ?? null;
const hasAssignedExpert = Array.isArray(rawExpert)
  ? rawExpert.length > 0
  : (typeof rawExpert === 'object' && rawExpert !== null)
    ? Object.keys(rawExpert).length > 0
    : (typeof rawExpert === 'number'
      ? rawExpert > 0
      : Boolean(String(rawExpert || '').trim()));

const expertMobilise = Boolean(
  hasAssignedExpert ||
  f.Expert_Mobilise === true ||
  (!isDecouverte && /affect|mobilis|assign|en mission|audit|arbitrage|livr|clotur|termin/.test(sNorm))
);

const statutLabelMap = {
  saisine_recue: 'Saisine reçue & scellée',
  dispatch_en_cours: 'Dispatch expert en cours (SLA 2h)',
  affectee: 'Expert senior mobilisé',
  affecte: 'Expert senior mobilisé',
  audit_en_cours: 'Audit & arbitrage en cours',
  en_audit: 'Audit & arbitrage en cours',
  livre: 'Livrable stratégique disponible',
  livree: 'Livrable stratégique disponible',
  livre_client: 'Livrable stratégique disponible',
  cloture: 'Clôturé',
  cloturee: 'Clôturé'
};

const palierLabelMap = {
  palier_1_decouverte: 'Palier 1 — Découverte',
  palier_2_certifie: 'Mandat Certifié',
  palier_3_chambre: 'Chambre Stratégique'
};

const secteurBrut = String(f.Secteur_Code || f.Secteur || f.Secteur_Activite || '').trim();
const secteurKey = normalizeKey(secteurBrut);
const secteurLabelMap = {
  agro: 'Agro-industrie & Souveraineté Alimentaire',
  energy: 'Énergie, Mines & Transition',
  energie: 'Énergie, Mines & Transition',
  banking: 'Banque, FinTech & Assurance',
  finance: 'Finance & Conformité',
  fintech: 'Fintech & Paiements',
  logistics: 'Logistique, Ports & Supply Chain',
  logistique: 'Logistique & Supply Chain',
  health: 'Santé, Pharma & Bio',
  sante: 'Santé & Biotech',
  telecom: 'Télécoms, Cloud & Infra',
  property: 'BTP, Immobilier & Foncier',
  btp: 'BTP & Aménagement',
  manufacturing: 'Industrie & Transformation',
  industrie: 'Industrie & Chaîne Logistique',
  public: 'Secteur Public & Para-public',
  retail: 'Distribution, Retail & Négoce',
  tech: 'Tech, IA & Souveraineté Numérique',
  ia: 'Tech, IA & Souveraineté Numérique',
  mines: 'Mines & Ressources'
};

const secteurAffiche = secteurKey.startsWith('code sectoriel') || !secteurBrut
  ? 'Audit Stratégique'
  : (secteurLabelMap[secteurKey] || secteurBrut);

let etape = 1;
let libelle = 'Saisine enregistrée & qualifiée';

if (/clotur|termin|archiv/.test(sNorm)) {
  etape = 5;
  libelle = 'Mandat clôturé & certifié';
} else if (/livr|rapport|restitu/.test(sNorm)) {
  etape = 4;
  libelle = 'Livrable stratégique disponible';
} else if (/audit|analyse|arbitrage|production/.test(sNorm)) {
  etape = 3;
  libelle = 'Audit & arbitrage stratégique en cours';
} else if (/affect|mobilis|assign|en mission/.test(sNorm) || expertMobilise) {
  etape = 2;
  libelle = 'Expert senior mobilisé';
} else if (/dispatch/.test(sNorm)) {
  etape = 1;
  libelle = 'Dispatch expert en cours (SLA 2h)';
}

const dtoPublic = {
  reference: String(f.Mission_Ref || f.Code_Mission || ref).trim(),
  statut: statutLabelMap[sNorm] || statutBrut,
  statut_brut: statutBrut,
  etape_courante: etape,
  etape_totale: 5,
  libelle_etape: libelle,
  palier: palierLabelMap[palierKey] || palierBrut || 'Mandat Certifié',
  secteur: secteurAffiche,
  expert_mobilise: expertMobilise,
  hash: f.Empreinte_SHA256 || f.Contrat_Hash_Ref || f.Hash_SHA256 || f.Hash_OTS || null,
  link: f.Rapport_URL || f.Lien_Livrable || f.Livrable_URL || f.webViewLink || null,
  mise_a_jour_utc: f.UpdatedAt || f.Updated_At || f.CreatedAt || record.updated_at || record.created_at || new Date().toISOString()
};

return [
  {
    json: {
      found: true,
      ok: true,
      statusCode: 200,
      payload: dtoPublic
    }
  }
];
